const linkBtn = row.querySelector('.btn-field-link');
if (linkBtn) {
    linkBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        startFieldLinker(row, fKey);
    });
}

// Logic điều chỉnh độ rộng label
const splitter = row.querySelector('.label-splitter');
if (splitter) {
    splitter.addEventListener('mousedown', (e) => {
        e.preventDefault();
        const startX = e.clientX;
        const containerWidth = AppState.fieldsContainer.offsetWidth || 400;
        // Lấy giá trị hiện tại của --label-flex từ style inline hoặc mặc định 0.2
        let currentFlex = parseFloat(getComputedStyle(AppState.fieldsContainer).getPropertyValue('--label-flex')) || 0.2;

        const onMouseMove = (moveEvent) => {
            const deltaX = moveEvent.clientX - startX;
            const deltaFlex = deltaX / containerWidth;
            let newFlex = Math.max(0.1, Math.min(0.8, currentFlex + deltaFlex));
            AppState.fieldsContainer.style.setProperty('--label-flex', newFlex);
        };

        const onMouseUp = () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
            saveFieldsToLocal(); // Lưu lại trạng thái nếu cần
        };

        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
    });
}

AppState.fieldsContainer.appendChild(row);

