export function syncToPage(data, calcMaps) {
    // Cập nhật giá trị vào bảng Fields UI (nếu đang ở chế độ mặc định)
    if (AppState.isDefaultMode && AppState.fieldsContainer) {
        const rows = AppState.fieldsContainer.querySelectorAll('.vnpt-field-row');
        rows.forEach(row => {
            const keyInput = row.querySelector('.f-key');
            const valInput = row.querySelector('.f-val');
            if (keyInput && valInput) {
                const pk = keyInput.value.split(',')[0].trim();
                if (pk === 'calcBefore') valInput.value = data.beforeStr;
                if (pk === 'calcTax') valInput.value = data.taxStr;
                if (pk === 'calcAfter') valInput.value = data.afterStr;
                if (pk === 'calcText') valInput.value = data.textStr;
            }
        });
    }

    const processMap = (mapInfo, value) => {
        if (!mapInfo) return;
        const targets = Array.isArray(mapInfo) ? mapInfo : (mapInfo.sync || []);
        targets.forEach(n => setPageField(n, value));
    };

    processMap(calcMaps.before, data.beforeStr);
    processMap(calcMaps.tax, data.taxStr);
    processMap(calcMaps.after, data.afterStr);
    processMap(calcMaps.text, data.textStr);
}

