const debouncedSync = debounce((type, val) => {
    doSync(type, val);

    // Cập nhật giá trị vào bảng Fields UI (nếu đang ở chế độ mặc định)
    if (AppState.isDefaultMode && AppState.fieldsContainer) {
        const rows = AppState.fieldsContainer.querySelectorAll('.vnpt-field-row');
        const res = calculateValues(type, val, TAX_RATE);
        rows.forEach(row => {
            const keyInput = row.querySelector('.f-key');
            const valInput = row.querySelector('.f-val');
            if (keyInput && valInput) {
                const pk = keyInput.value.split(',')[0].trim();
                let updatedVal = null;
                if (pk === 'calcBefore') updatedVal = res.beforeStr;
                else if (pk === 'calcTax') updatedVal = res.taxStr;
                else if (pk === 'calcAfter') updatedVal = res.afterStr;
                else if (pk === 'calcText') updatedVal = res.textStr;

                if (updatedVal !== null && valInput.value !== updatedVal) {
                    valInput.value = updatedVal;
                    // Kích hoạt sự kiện input để lưu vào LocalStorage
                    valInput.dispatchEvent(new Event('input', { bubbles: true }));
                }
            }
        });
    }
}, 400);

