Object.keys(DEFAULT_DATA).forEach(pk => {
    const def = DEFAULT_DATA[pk];
    if (def.isCalcMapping) {
        const ck = def.calcKey;
        const ovr = overrides[pk] || def;

        // Nếu người dùng không nhập gì trong f-key (sync rỗng)
